subsection.content:
Syntaxe algorithmique :

TYPE nom_type_enregistrement = ENREGISTREMENT

  Champ1 : Type1 ;

  Champ2 : Type2 ;

  ...

  ChampN : TypeN ;

FIN ;

En langage C :

STRUCT nom_type_enregistrement

{

  Type1 Champ1 ;

  Type2 Champ2 ;

  ...

  TypeN ChampN ;

} ;

TYPE Facture = Enregistrement

  NoFacture : Entier ;

  Montant : Réel ;

FIN ;

Exemple :

TYPE Enregistrement1 = ENREGISTREMENT

  a : Entier ;

  b : Réel ;

  c : Char ;

FIN ;


TYPE Enregistrement2 = ENREGISTREMENT

  a : Char ;

  b, c : Réel ;

FIN ;

ALGORITHME exemple1 ;

TYPE Compte = ENREGISTREMENT

  NoCompte : Entier ;

  Nom : Chaîne de caractères ;

FIN ;

VAR Client : Compte ;

DÉBUT

  ÉCRIRE('Entrez le numéro de compte et nom du client');

  LIRE(Client.NoCompte) ;

  LIRE(Client.Nom) ;

  ÉCRIRE('Le numéro de compte du client est : ', Client.NoCompte);

  ÉCRIRE('Le nom du Client est : ', Client.Nom);

FIN.

ALGORITHME exemple2 ;

CONST dim = 3 ;

TYPE Compte = ENREGISTREMENT

  NoCompte : Entier ;

  Nom : Chaîne de caractères ;

FIN ;

VAR C : Tableau [1..dim] DE Compte ;

i : Entier ;

DÉBUT

  POUR i ALLANT DE 1 A dim FAIRE

    ÉCRIRE('Entrez le numéro de compte du client') ;

    LIRE(C[i].NoCompte) ;

    ÉCRIRE('Entrez le nom du client') ;

    LIRE(C[i].Nom) ;

  FIN POUR ;

  ÉCRIRE('Voici le tableau d'enregistrements saisi : ');

  POUR i ALLANT DE 1 A dim FAIRE

    ÉCRIRE('Numéro de compte du client ', i, ' est : ', C[i].NoCompte) ;

    ÉCRIRE('Le nom du client ', i, ' est : ', C[i].Nom) ;

  FIN POUR ;

FIN.

ALGORITHME exemple3 ;

TYPE Date = ENREGISTREMENT

  Jour : 1 .. 31 ;

  Mois : 1 .. 12 ;

  Année : 2000 .. 2021 ;

FIN ;


TYPE Compte = ENREGISTREMENT

  NoCompte : Entier ;

  Nom : Chaîne de caractères ;

  DateOuverture : Date ;

FIN ;

VAR Client : Compte ;

DÉBUT

  ÉCRIRE('Entrez le numéro de compte du client') ;

  LIRE(Client.NoCompte) ;

  ÉCRIRE('Entrez le nom du client') ;

  LIRE(Client.Nom) ;

  ÉCRIRE('Entrez le jour d'ouverture du compte') ;

  LIRE(Client.DateOuverture.Jour) ;

  ÉCRIRE('Entrez le mois d'ouverture du compte') ;

  LIRE(Client.DateOuverture.Mois) ;

  ÉCRIRE('Entrez l'année d'ouverture du compte') ;

  LIRE(Client.DateOuverture.Année) ;

  ÉCRIRE('Voici l'enregistrement saisi') ;

  ÉCRIRE(Client.NoCompte, ' ', Client.Nom) ;

  ÉCRIRE(Client.DateOuverture.Jour, ' / ', Client.DateOuverture.Mois, ' / ', Client.DateOuverture.Année) ;

FIN.

AVEC enregistrement FAIRE

  instruction(s) ;

FIN AVEC ;

AVEC Client FAIRE

  ÉCRIRE(NoCompte) ;

  ÉCRIRE(Nom) ;

  ÉCRIRE(DateOuverture.Jour, '/', DateOuverture.Mois, '/', DateOuverture.Année) ;

FIN AVEC ;

TYPE Nom_type_enregistrement = ENREGISTREMENT

  Champ1 : Type1 ;

  Champ2 : Type2 ;

  ...

  ChampN : TypeN ;

FIN ;


PROCÉDURE nom_procedure (nom_variable : Nom_type_enregistrement);

(OU FONCTION nom_fonction (nom_variable : Nom_type_enregistrement) : Type ;)

DÉBUT

  Instruction(s) ;

FIN ;

ALGORITHME exemple4 ;

TYPE Compte = ENREGISTREMENT

  NoCompte : Entier ;

  Nom : Chaîne de caractères ;

  Solde : Réel ;

FIN ;

VAR Client : Compte ;


PROCÉDURE Proc_affichage (x : Compte) ;

DÉBUT

  ÉCRIRE('Affichage dans la procédure : ');

  ÉCRIRE('Le numéro de compte du client : ', x.NoCompte);

  ÉCRIRE('Le nom du client : ', x.Nom);

  ÉCRIRE('Le solde du client : ', x.Solde);

FIN ;


DÉBUT

  ÉCRIRE('Affichage dans l'algorithme principal');

  AVEC Client FAIRE

    LIRE(NoCompte);

    LIRE(Nom);

    LIRE(Solde);

  FIN AVEC ;

  Proc_affichage(Client);

FIN.
